import { type TeamHuntState } from "@hunt/public-client";
import React from "react";
import { hydrateRoot } from "react-dom/client";
import HubBody from "../hub/HubBody";
import useDataset from "./useDataset";

const HubManager = ({
  initialTeamState,
}: {
  initialTeamState: TeamHuntState;
}) => {
  const teamState = useDataset("team_state", undefined, initialTeamState);
  return <HubBody teamState={teamState} />;
};

const hubElem = document.getElementById("hub-root");
if (hubElem) {
  const initialTeamState = (
    window as unknown as { initialTeamState: TeamHuntState }
  ).initialTeamState;
  hydrateRoot(hubElem, <HubManager initialTeamState={initialTeamState} />);
} else {
  console.error("Couldn't mount Hub because #hub-root was nowhere to be found");
}
