import {
  autoUpdate,
  flip,
  offset,
  shift,
  type Placement,
  useFloating,
} from "@floating-ui/react";
import { type TeamHuntState } from "@hunt/public-client";
import { Lock, Puzzle as PuzzleIcon } from "lucide-react";
import React, {
  type KeyboardEventHandler,
  type MouseEventHandler,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  PuzzleUnlockModal,
  type PuzzleStateHandle,
} from "../components/PuzzleUnlockModal";
import { RoundUnlockModal } from "../components/RoundUnlockModal";
import { TeamStateProvider } from "../components/TeamStateProvider";
import { type TooltipPosition } from "../types/tooltip";
import { centerFloatingMiddleware } from "../utils/floating";
import { IS_STATIC_SITE } from "../utils/staticSite";
import { HubFonts } from "./HubFonts";
import PrehuntHub from "./PrehuntHub";
import FinalPortal from "./assets/final_portal.gif";
import BottomClouds from "./assets/misc/cloud_background.png";
import ExclamationIcon from "./assets/misc/exclamation.svg";
import WaterBackground from "./assets/misc/water_bg_transparent.png";
import MapBackground from "./assets/zones/Background.png";
import { type OverworldObject } from "./types";
import { toHubState, ZONE_BASE_POSITION } from "./index";

// For debugging purposes
const SHOW_BOUNDARY_OVERLAYS = false;
const FINAL_PORTAL_SIZE = { width: 64, height: 448 } as const;
const FINAL_PORTAL_FIXED_POSITION = {
  right: 0,
  top: `calc(50% - ${FINAL_PORTAL_SIZE.height / 2}px)`,
} as const;

const HubBody = ({ teamState }: { teamState: TeamHuntState }) => {
  const hubState = toHubState(teamState);
  const [roundModalObj, setRoundModalObj] = useState<OverworldObject | null>(
    null,
  );
  const [activePuzzleSlug, setActivePuzzleSlug] = useState<string | null>(null);
  const [tooltip, setTooltip] = useState<{
    slug: string;
    content: React.ReactNode;
    position: TooltipPosition;
  } | null>(null);

  const roundUnlockModalRef = useRef<HTMLDialogElement>(null);
  const buttonRefs = useRef<Record<string, HTMLElement | null>>({});

  useEffect(() => {
    if (roundModalObj?.round_unlock) {
      roundUnlockModalRef.current?.showModal();
    } else {
      roundUnlockModalRef.current?.close();
    }
  }, [roundModalObj]);

  const hideTooltip = useCallback(() => {
    setTooltip(null);
  }, []);

  const shouldRenderBottomClouds = useMemo(() => {
    return hubState.overworld_objects.some(
      (obj) => obj.type === "research_meta" && !obj.inert,
    );
  }, [hubState.overworld_objects]);

  const hasAvailableZones = useMemo(() => {
    return hubState.overworld_objects.some(
      (obj) => obj.type === "zone" && !obj.inert,
    );
  }, [hubState.overworld_objects]);

  const isAviariaUnlocked = hubState.rounds.some(
    (round) => round.slug === "aviaria" && round.locked === "unlocked",
  );
  const shouldShowPrehuntHub = !isAviariaUnlocked || !hasAvailableZones;
  const finalPortalPuzzle = teamState.puzzles.to_the_edge;
  const shouldShowFinalPortal = Boolean(
    finalPortalPuzzle &&
      (finalPortalPuzzle.locked === "unlocked" || finalPortalPuzzle.solved),
  );
  const finalPortalObject: OverworldObject = {
    slug: "to_the_edge",
    name: "To the Edge",
    x: 0,
    y: 0,
    type: "research_meta",
    asset: FinalPortal,
    href: "/puzzles/to_the_edge",
    tooltip_position: "left",
    z_index: 60,
    fixed_position: FINAL_PORTAL_FIXED_POSITION,
  };

  const dismissRoundModal = useCallback(() => {
    setRoundModalObj(null);
  }, []);

  const dismissPuzzleModal = useCallback(() => {
    setActivePuzzleSlug(null);
  }, []);

  const registerObjectRef = useCallback(
    (slug: string, element: HTMLElement | null) => {
      buttonRefs.current[slug] = element;
    },
    [],
  );

  useEffect(() => {
    if (!activePuzzleSlug) {
      return;
    }
    const activeButton = buttonRefs.current[activePuzzleSlug];
    if (!activeButton) {
      setActivePuzzleSlug(null);
    }
  }, [activePuzzleSlug]);

  const tooltipPosition = tooltip?.position ?? "top";
  const isCenterTooltip = tooltipPosition === "center";
  const floatingPlacement: Placement = isCenterTooltip
    ? "top"
    : (tooltipPosition as Exclude<TooltipPosition, "center">);

  const tooltipMiddleware = useMemo(
    () =>
      isCenterTooltip
        ? [centerFloatingMiddleware, shift()]
        : [offset(10), flip(), shift()],
    [isCenterTooltip],
  );

  const { refs, floatingStyles } = useFloating({
    placement: floatingPlacement,
    middleware: tooltipMiddleware,
    open: Boolean(tooltip),
    whileElementsMounted: autoUpdate,
  });

  const getTooltipContent = useCallback((object: OverworldObject) => {
    const isResearchMeta = Boolean(
      object.puzzle_unlock || object.href?.startsWith("/puzzles/"),
    );
    const isUnlockableZone = !IS_STATIC_SITE && Boolean(object.round_unlock);
    const isUnlockableMeta = !IS_STATIC_SITE && Boolean(object.puzzle_unlock);
    const isUnlockedMeta = isResearchMeta && !isUnlockableMeta;
    const isUnlockedZone = !isResearchMeta && !isUnlockableZone;

    const label = isResearchMeta
      ? (object.puzzle_unlock?.title ?? object.name)
      : (object.round_unlock?.title ?? object.name);

    if (!isResearchMeta && !isUnlockableZone && !isUnlockedZone) {
      return <span>{label}</span>;
    }

    if (isUnlockableZone || isUnlockableMeta) {
      return (
        <span className="flex items-center gap-2">
          <Lock className="h-4 w-4" />
          <span>{label}</span>
        </span>
      );
    }

    if (isUnlockedMeta) {
      return (
        <span className="flex items-center gap-2">
          <PuzzleIcon className="h-4 w-4" />
          <span>{label}</span>
        </span>
      );
    }

    return <span>{label}</span>;
  }, []);

  const showTooltip = useCallback(
    (object: OverworldObject) => {
      const button = buttonRefs.current[object.slug];
      if (!button) {
        return;
      }
      const content = getTooltipContent(object);
      if (!content) {
        setTooltip(null);
        return;
      }
      const position = object.tooltip_position ?? "center";
      refs.setReference(button);
      setTooltip({
        slug: object.slug,
        content,
        position,
      });
    },
    [getTooltipContent, refs],
  );

  return (
    <>
      <TeamStateProvider teamState={teamState}>
        <HubFonts />
        <div id="main-content">
          {!shouldShowPrehuntHub && shouldShowFinalPortal && (
            <OverworldObjectButton
              object={finalPortalObject}
              registerButton={registerObjectRef}
              showTooltip={showTooltip}
              hideTooltip={hideTooltip}
              setRoundModalObj={setRoundModalObj}
              setActivePuzzleSlug={setActivePuzzleSlug}
              activePuzzleSlug={activePuzzleSlug}
              dismissPuzzleModal={dismissPuzzleModal}
            />
          )}
          <div
            className="min-w-[960px] min-h-screen flex justify-center"
            style={{
              backgroundColor: "#032b63",
              backgroundImage: `url(${WaterBackground})`,
              backgroundRepeat: "repeat",
              imageRendering: "pixelated",
            }}
          >
            <div className="w-full flex justify-center">
              <div className="w-full max-w-[960px] pt-12 flex flex-col items-center gap-12">
                <div className="w-[960px] mx-auto">
                  {shouldShowPrehuntHub ? (
                    <PrehuntHub />
                  ) : (
                    <div
                      className="relative"
                      style={{
                        height: shouldRenderBottomClouds ? "1280px" : "960px",
                        width: "960px",
                      }}
                      onMouseLeave={hideTooltip}
                    >
                      <img
                        src={MapBackground}
                        alt=""
                        aria-hidden="true"
                        className="pointer-events-none absolute select-none"
                        style={{
                          top: ZONE_BASE_POSITION.y,
                          left: ZONE_BASE_POSITION.x,
                          imageRendering: "pixelated",
                        }}
                      />
                      {shouldRenderBottomClouds && (
                        <img
                          src={BottomClouds}
                          alt=""
                          aria-hidden="true"
                          className="pointer-events-none absolute select-none left-28 bottom-4 z-[5]"
                        />
                      )}
                      {hubState.overworld_objects.map((object) => (
                        <OverworldObjectButton
                          key={object.slug}
                          object={object}
                          registerButton={registerObjectRef}
                          showTooltip={showTooltip}
                          hideTooltip={hideTooltip}
                          setRoundModalObj={setRoundModalObj}
                          setActivePuzzleSlug={setActivePuzzleSlug}
                          activePuzzleSlug={activePuzzleSlug}
                          dismissPuzzleModal={dismissPuzzleModal}
                        />
                      ))}
                      {tooltip && (
                        <div
                          ref={refs.setFloating}
                          className="pointer-events-none absolute z-50 flex items-center gap-2 rounded-md bg-white px-3 py-1.5 text-sm font-medium text-black shadow-lg"
                          style={floatingStyles}
                        >
                          {tooltip.content}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>

        {!IS_STATIC_SITE && roundModalObj?.round_unlock && (
          <RoundUnlockModal
            ref={roundUnlockModalRef}
            onDismiss={dismissRoundModal}
            cost={roundModalObj.round_unlock.cost ?? 1}
            currency={hubState.currency}
            slug={roundModalObj.round_unlock.slug ?? ""}
            title={roundModalObj.round_unlock.title ?? ""}
            desc={roundModalObj.round_unlock.desc}
          />
        )}
      </TeamStateProvider>
    </>
  );
};

const boundarySvgCache = new Map<string, string>();

const useBoundarySvg = (url?: string) => {
  const [svgMarkup, setSvgMarkup] = useState<string | null>(
    url ? (boundarySvgCache.get(url) ?? null) : null,
  );

  useEffect(() => {
    if (!url) {
      setSvgMarkup(null);
      return;
    }
    const cached = boundarySvgCache.get(url);
    if (cached) {
      setSvgMarkup(cached);
      return;
    }
    let cancelled = false;
    fetch(url)
      .then((response) => {
        if (!response.ok) {
          throw new Error(`Failed to load boundary svg for ${url}`);
        }
        return response.text();
      })
      .then((text) => {
        if (cancelled) {
          return;
        }
        boundarySvgCache.set(url, text);
        setSvgMarkup(text);
      })
      .catch(() => {
        if (!cancelled) {
          setSvgMarkup(null);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [url]);

  return svgMarkup;
};

const OverworldObjectButton = ({
  object,
  registerButton,
  showTooltip,
  hideTooltip,
  setRoundModalObj,
  setActivePuzzleSlug,
  activePuzzleSlug,
  dismissPuzzleModal,
}: {
  object: OverworldObject;
  registerButton: (slug: string, element: HTMLElement | null) => void;
  showTooltip: (object: OverworldObject) => void;
  hideTooltip: () => void;
  setRoundModalObj: (object: OverworldObject) => void;
  setActivePuzzleSlug: (slug: string | null) => void;
  activePuzzleSlug: string | null;
  dismissPuzzleModal: () => void;
}) => {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const boundaryRef = useRef<HTMLElement | null>(null);
  const boundarySvg = useBoundarySvg(object.boundary_asset);
  const hasBoundary = Boolean(boundarySvg && object.boundary_asset);
  const [isHovered, setIsHovered] = useState(false);
  const [isFocused, setIsFocused] = useState(false);
  const isInteractive = Boolean(
    !object.inert &&
      (object.href || object.round_unlock || object.puzzle_unlock),
  );
  const isActivePuzzle = activePuzzleSlug === object.slug;

  const hasFixedPosition = Boolean(object.fixed_position);
  const containerClasses = [
    hasFixedPosition ? "fixed" : "absolute",
    "inline-block",
    isInteractive ? "transition-transform duration-200" : "",
    isInteractive && (isHovered || isFocused) ? "-translate-y-1" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const containerStyle: React.CSSProperties = {
    ...(hasFixedPosition
      ? object.fixed_position
      : {
          top: object.y,
          left: object.x,
        }),
    zIndex: object.z_index ?? 10,
    pointerEvents: hasBoundary ? "none" : undefined,
  };

  const showUnlockableIndicator =
    !IS_STATIC_SITE &&
    (object.type === "zone" || object.type === "dimension") &&
    Boolean(object.round_unlock);

  const isHighlighted = isInteractive && (isHovered || isFocused);

  const imageClasses = [
    "pointer-events-none select-none",
    isInteractive ? "transition-[filter] duration-200" : "",
    isHighlighted
      ? "transform-gpu drop-shadow-[0_0_16px_rgba(255,255,255,0.6)]"
      : "",
  ]
    .filter(Boolean)
    .join(" ");

  const boundaryClasses = [
    "absolute left-0 top-0 inline-block border-none bg-transparent p-0 z-10",
    SHOW_BOUNDARY_OVERLAYS ? "opacity-60" : "opacity-0",
  ]
    .filter(Boolean)
    .join(" ");

  const registerInteractiveRef = useCallback(
    (element: HTMLElement | null) => {
      boundaryRef.current = element;
      registerButton(object.slug, element);
    },
    [object.slug, registerButton],
  );

  const handleActivation: MouseEventHandler<HTMLElement> = useCallback(
    (event) => {
      event.stopPropagation();
      if (object.href) {
        window.location.href = object.href;
        return;
      }
      if (!IS_STATIC_SITE && object.round_unlock) {
        setRoundModalObj(object);
        return;
      }
      if (!IS_STATIC_SITE && object.puzzle_unlock) {
        setActivePuzzleSlug(object.slug);
        hideTooltip();
      }
    },
    [hideTooltip, object, setActivePuzzleSlug, setRoundModalObj],
  );

  const handleKeyDown: KeyboardEventHandler<HTMLElement> = useCallback(
    (event) => {
      if (!isInteractive) {
        return;
      }
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        handleActivation(event as unknown as React.MouseEvent<HTMLElement>);
      }
    },
    [handleActivation, isInteractive],
  );

  const handleMouseEnter = useCallback(() => {
    setIsHovered(true);
    showTooltip(object);
  }, [object, showTooltip]);

  const handleMouseLeave = useCallback(() => {
    setIsHovered(false);
    hideTooltip();
  }, [hideTooltip]);

  const handleFocus = useCallback(() => {
    setIsFocused(true);
    showTooltip(object);
  }, [object, showTooltip]);

  const handleBlur = useCallback(() => {
    setIsFocused(false);
    hideTooltip();
  }, [hideTooltip]);

  useEffect(() => {
    if (!object.puzzle_unlock || IS_STATIC_SITE) {
      return;
    }
    const dialog = dialogRef.current;
    if (!dialog) {
      return;
    }
    if (isActivePuzzle) {
      if (!dialog.open) {
        dialog.showModal();
      }
    } else if (dialog.open) {
      dialog.close();
    }
  }, [isActivePuzzle, object.puzzle_unlock]);

  const puzzleStateHandle: PuzzleStateHandle | null = useMemo(() => {
    if (!object.puzzle_unlock || IS_STATIC_SITE) {
      return null;
    }
    return [
      {
        slug: object.puzzle_unlock.slug ?? object.slug,
        title: object.puzzle_unlock.title ?? object.name,
        state: "unlockable",
        desc: object.puzzle_unlock.desc,
        unlock_cost: object.puzzle_unlock.cost,
        is_overworld_feeder: object.puzzle_unlock.is_overworld_feeder ?? false,
      },
      () => {
        setActivePuzzleSlug(null);
      },
    ];
  }, [object, setActivePuzzleSlug]);

  useEffect(() => {
    if (!boundarySvg || !boundaryRef.current) {
      return;
    }
    const svgElement = boundaryRef.current.querySelector<SVGSVGElement>("svg");
    if (!svgElement) {
      return;
    }

    const shapeTargets = Array.from(
      svgElement.querySelectorAll<SVGGraphicsElement>(
        "path, polygon, polyline, rect, circle, ellipse",
      ),
    );
    const pointerTargets =
      shapeTargets.length > 0 ? shapeTargets : [svgElement];

    svgElement.style.pointerEvents = shapeTargets.length
      ? "none"
      : "visiblePainted";
    svgElement.tabIndex = isInteractive ? 0 : -1;
    svgElement.setAttribute("role", isInteractive ? "button" : "img");

    pointerTargets.forEach((element) => {
      element.style.pointerEvents = "visiblePainted";
      element.style.cursor = isInteractive ? "pointer" : "default";
      element.addEventListener("mouseenter", handleMouseEnter);
      element.addEventListener("mouseleave", handleMouseLeave);
      element.addEventListener(
        "click",
        handleActivation as unknown as EventListener,
      );
    });

    svgElement.addEventListener("focus", handleFocus);
    svgElement.addEventListener("blur", handleBlur);
    svgElement.addEventListener(
      "keydown",
      handleKeyDown as unknown as EventListener,
    );

    return () => {
      pointerTargets.forEach((element) => {
        element.removeEventListener("mouseenter", handleMouseEnter);
        element.removeEventListener("mouseleave", handleMouseLeave);
        element.removeEventListener(
          "click",
          handleActivation as unknown as EventListener,
        );
      });
      svgElement.removeEventListener("focus", handleFocus);
      svgElement.removeEventListener("blur", handleBlur);
      svgElement.removeEventListener(
        "keydown",
        handleKeyDown as unknown as EventListener,
      );
    };
  }, [
    boundarySvg,
    handleActivation,
    handleBlur,
    handleFocus,
    handleKeyDown,
    handleMouseEnter,
    handleMouseLeave,
    isInteractive,
  ]);

  if (!hasBoundary) {
    const fallbackButtonClasses = [
      containerClasses,
      "border-none bg-transparent p-0 z-10",
      isInteractive ? "cursor-pointer focus:outline-none" : "cursor-default",
    ]
      .filter(Boolean)
      .join(" ");

    return (
      <>
        <button
          type="button"
          className={fallbackButtonClasses}
          style={containerStyle}
          onClick={isInteractive ? handleActivation : undefined}
          onKeyDown={isInteractive ? handleKeyDown : undefined}
          onMouseEnter={handleMouseEnter}
          onFocus={handleFocus}
          onMouseLeave={handleMouseLeave}
          onBlur={handleBlur}
          aria-label={object.name}
          disabled={!isInteractive}
          ref={(el) => {
            registerInteractiveRef(el);
          }}
        >
          <img
            src={object.asset}
            alt=""
            aria-hidden="true"
            className={imageClasses}
            style={{ imageRendering: "pixelated" }}
          />
          {showUnlockableIndicator && (
            <img
              src={ExclamationIcon}
              alt="New zone available"
              aria-hidden="true"
              className="pointer-events-none absolute left-1/2 top-1/2 z-20 h-8 w-8 -translate-x-1/2 -translate-y-1/2 transform-gpu drop-shadow-[0_0_12px_rgba(255,255,255,0.8)]"
              style={{ imageRendering: "pixelated" }}
            />
          )}
        </button>
        {!IS_STATIC_SITE && object.puzzle_unlock && puzzleStateHandle && (
          <PuzzleUnlockModal
            ref={dialogRef}
            onDismiss={dismissPuzzleModal}
            stateHandle={puzzleStateHandle}
            cost={object.puzzle_unlock.cost ?? 1}
          />
        )}
      </>
    );
  }

  return (
    <>
      <div className={containerClasses} style={containerStyle}>
        <img
          src={object.asset}
          alt=""
          aria-hidden="true"
          className={imageClasses}
          style={{ imageRendering: "pixelated" }}
        />
        <div
          className={boundaryClasses}
          style={{
            pointerEvents: "none",
          }}
          ref={(el) => {
            registerInteractiveRef(el);
          }}
          dangerouslySetInnerHTML={{ __html: boundarySvg ?? "" }}
        />
        {showUnlockableIndicator && (
          <img
            src={ExclamationIcon}
            alt="New zone available"
            aria-hidden="true"
            className="pointer-events-none absolute left-1/2 top-1/2 z-20 h-8 w-8 -translate-x-1/2 -translate-y-1/2 transform-gpu drop-shadow-[0_0_12px_rgba(255,255,255,0.8)]"
            style={{ imageRendering: "pixelated" }}
          />
        )}
      </div>
      {!IS_STATIC_SITE && object.puzzle_unlock && puzzleStateHandle && (
        <PuzzleUnlockModal
          ref={dialogRef}
          onDismiss={dismissPuzzleModal}
          stateHandle={puzzleStateHandle}
          cost={object.puzzle_unlock.cost ?? 1}
          physicalPresenceRequirement={
            object.puzzle_unlock.physical_presence_requirement
          }
        />
      )}
    </>
  );
};

export default HubBody;
