import React from "react";
import PuzzleCard from "../components/PuzzleAndTaskDisplay/PuzzleCard";
import { useTeamState } from "../components/TeamStateProvider";

const PrehuntHub = () => {
  const teamState = useTeamState();
  const huntAlmostStarted = teamState.gates_satisfied.includes(
    "hunt_almost_started",
  );
  const huntStarted = teamState.gates_satisfied.includes("hunt_started");
  const howToHuntPuzzle = teamState.puzzles?.how_to_hunt;
  const howToHuntSolved = !!teamState.puzzles?.how_to_hunt?.answer;
  const prizeOptions = howToHuntPuzzle?.task_info?.prize_options;
  const howToHuntPrizeMax =
    prizeOptions && Object.values(prizeOptions).length > 0
      ? Math.max(...Object.values(prizeOptions))
      : undefined;
  const showHowToHuntTask = huntAlmostStarted && !!howToHuntPuzzle;
  const howToHuntDescription =
    "Watch this introductory video to prepare your team for the hunt!";

  if (!huntAlmostStarted) {
    return <></>;
  }

  const message = huntStarted
    ? "Hunt is now underway! Please take a look at the following before you get started!"
    : howToHuntSolved
      ? "Hunt starting soon! The page will automatically update when the hunt starts."
      : "Hunt starting soon! Please take a look at the following!";

  return (
    <div className="flex flex-col items-center w-full max-w-[100vw] mt-12 px-4">
      {/* <h1 className="font-bold text-accent text-lg sm:text-2xl md:text-3xl lg:text-4xl">
        How to Hunt
      </h1>
      <span className="font-bold text-accent text-sm sm:text-base md:text-lg lg:text-xl mb-4">
        {howToHuntDescription}
      </span>
      <iframe
        title="how_to_hunt"
        className="w-full aspect-video rounded-lg shadow-lg"
        src="https://www.youtube.com/embed/_EY5CxqQPKI"
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
        allowFullScreen
      ></iframe> */}
      <div className="mt-8 text-accent text-2xl md:text-3xl font-bold text-center">
        {message}
      </div>
      {showHowToHuntTask && howToHuntPuzzle && (
        <div className="w-full max-w-screen-lg mt-6">
          <PuzzleCard
            lockState={howToHuntPuzzle.locked}
            title="How to Hunt"
            slug="how_to_hunt"
            desc={howToHuntDescription}
            solved={howToHuntPuzzle.solved}
            unlock_cost={howToHuntPuzzle.unlock_cost}
            is_overworld_feeder={howToHuntPuzzle.is_overworld_feeder}
            prize={howToHuntPuzzle.prize}
            prizeMax={howToHuntPrizeMax}
            submissionType={howToHuntPuzzle.task_info?.submission_type}
            taskSubmissionState={howToHuntPuzzle.task_submission_state}
          />
        </div>
      )}
    </div>
  );
};

export default PrehuntHub;
